    const { data, error } = await supabase.from("posts").select("id, title, slug, excerpt, topic, created_at").eq("status", "approved").or(`title.ilike.${like},excerpt.ilike.${like}`).order("created_at", { ascending: false }).limit(limit ?? 10);
